-- Hyprland Lua Config Entrypoint
-- Modularized configuration structure

-- 1. Wallust colors (generated by wallust)
dofile(os.getenv("HOME") .. "/.config/hypr/wallust/wallust-hyprland.lua")

-- 2. Environment Variables
hl.env("DOTS_VERSION", "2.3.24")
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("CLUTTER_BACKEND", "wayland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "1")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QT_QPA_PLATFORMTHEME", "qt5ct")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_STYLE_OVERRIDE", "kvantum")
hl.env("QT_QUICK_CONTROLS_STYLE", "org.hyprland.style")
hl.env("GDK_SCALE", "1")
hl.env("QT_SCALE_FACTOR", "1")
hl.env("HYPRCURSOR_THEME", "capitaine-cursors")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("MOZ_ENABLE_WAYLAND", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("NVD_BACKEND", "direct")
hl.env("GSK_RENDERER", "ngl")
hl.env("EDITOR", "nvim")
hl.env("XCURSOR_THEME", "capitaine-cursors")
hl.env("XCURSOR_SIZE", "24")

-- 3. Load Modules
local HOME = os.getenv("HOME")
dofile(HOME .. "/.config/hypr/lua/monitors.lua")
dofile(HOME .. "/.config/hypr/lua/settings.lua")
dofile(HOME .. "/.config/hypr/lua/autostart.lua")
dofile(HOME .. "/.config/hypr/lua/keybinds.lua")
dofile(HOME .. "/.config/hypr/lua/rules.lua")
